import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../../core/data/product_repository.dart';
import '../../core/models/business_models.dart';
import '../../shared/irkop_ui.dart';
class ProductsPage extends StatefulWidget {const ProductsPage({super.key,this.businessId});final String? businessId;@override State<ProductsPage> createState()=>_ProductsPageState();}
class _ProductsPageState extends State<ProductsPage>{final _repo=ProductRepository();late Future<List<Product>> _future;String _query='';@override void initState(){super.initState();_future=widget.businessId==null?Future.value(const []):_repo.loadProducts(widget.businessId!);}
@override Widget build(BuildContext context){final money=NumberFormat.currency(locale:'id_ID',symbol:'Rp ',decimalDigits:0);return FutureBuilder<List<Product>>(future:_future,builder:(context,s){final data=(s.data??const <Product>[]).where((p)=>p.name.toLowerCase().contains(_query.toLowerCase())||p.category.toLowerCase().contains(_query.toLowerCase())).toList();return ListView(padding:const EdgeInsets.all(16),children:[const IrkopSectionHeader(eyebrow:'Produk & stok',title:'Katalog Produk',subtitle:'Cari dan pantau produk.',icon:Icons.inventory_2_outlined,action:'Database'),const SizedBox(height:14),TextField(decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari produk',border:OutlineInputBorder()),onChanged:(v)=>setState(()=>_query=v)),const SizedBox(height:12),if(s.connectionState!=ConnectionState.done)const Center(child:Padding(padding:EdgeInsets.all(32),child:CircularProgressIndicator())),if(s.hasError)Text('Gagal memuat: '+s.error.toString()),if(s.connectionState==ConnectionState.done&&!s.hasError&&data.isEmpty)const EmptyStateCard(icon:Icons.inventory_2_outlined,title:'Belum ada produk',subtitle:'Tambahkan produk dari katalog.'),...data.map((p)=>Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.inventory_2_outlined)),title:Text(p.name),subtitle:Text(p.category+' • Stok '+p.stock.toStringAsFixed(0)),trailing:Text(money.format(p.price),style:const TextStyle(fontWeight:FontWeight.w800)))))]);});}}